/**
 * 事务内锁定“主体＋用途”当前最新代次行（批次查询与撤回/重新授权互斥，按提交顺序裁决）。
 *
 * <p>先读最新代次再按主键加锁并重读，循环到代次稳定，避免插入新代次的幻读窗口。
 */
Optional<GrantRow> lockLatestGrant(String subjectKey, Purpose purpose) {
    GrantRow target = findLatestGrant(subjectKey, purpose).orElse(null);
    if (target == null) {
        return Optional.empty();
    }
    for (int i = 0; i < 5; i++) {
        lockGrant(subjectKey, purpose, target.epoch()).orElseThrow();
        GrantRow reloaded = findLatestGrant(subjectKey, purpose).orElseThrow();
        if (reloaded.epoch() == target.epoch()) {
            return Optional.of(reloaded);
        }
        target = reloaded;
    }
    return lockGrant(subjectKey, purpose, target.epoch());
}

/**
 * 按主键锁定指定授权代次行。
 */
Optional<GrantRow> lockGrant(String subjectKey, Purpose purpose, int epoch) {
    List<GrantRow> rows = jdbc.query(
            "SELECT subject_key, purpose, epoch, status FROM consent_grant"
                    + " WHERE subject_key = ? AND purpose = ? AND epoch = ? FOR UPDATE",
            GRANT_MAPPER, subjectKey, purpose.name(), epoch);
    return rows.stream().findFirst();
}

